-- Script adaptado de MySQL 8 a H2 2.x
-- Base prevista: jdbc:h2:mem:medios_de_pago;DB_CLOSE_DELAY=-1
-- No incluye CREATE DATABASE ni USE: la base se selecciona en la URL JDBC.

SET REFERENTIAL_INTEGRITY FALSE;

DROP TABLE IF EXISTS movimientos;
DROP TABLE IF EXISTS tipos_movimientos;
DROP TABLE IF EXISTS tarjetas;
DROP TABLE IF EXISTS extractos;
DROP TABLE IF EXISTS cuentas;
DROP TABLE IF EXISTS clientes;
DROP TABLE IF EXISTS personas;

-- Estructura

CREATE TABLE personas (
    id_persona INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre varchar(45) NOT NULL,
    apellido1 varchar(45) NOT NULL,
    apellido2 varchar(45) DEFAULT NULL,
    nif varchar(45) NOT NULL,
    sexo varchar(1) NOT NULL,
    municipio varchar(45) NOT NULL,
    provincia varchar(45) NOT NULL,
    PRIMARY KEY (id_persona)
);

CREATE TABLE clientes (
    id_cliente INTEGER NOT NULL,
    nrocliente INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY (id_cliente),
    CONSTRAINT clientes_personas FOREIGN KEY (id_cliente) REFERENCES personas (id_persona)
);

CREATE TABLE cuentas (
    id_cuenta INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    numero varchar(45) NOT NULL,
    fk_cliente INTEGER NOT NULL,
    PRIMARY KEY (id_cuenta),
    CONSTRAINT cuentas_clientes FOREIGN KEY (fk_cliente) REFERENCES clientes (id_cliente)
);

CREATE TABLE extractos (
    id_extracto INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fk_cuenta INTEGER NOT NULL,
    anyo INTEGER NOT NULL,
    mes INTEGER NOT NULL,
    PRIMARY KEY (id_extracto),
    CONSTRAINT extractos_cuentas FOREIGN KEY (fk_cuenta) REFERENCES cuentas (id_cuenta)
);

CREATE TABLE tarjetas (
    id_tarjeta INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    pan varchar(16) NOT NULL,
    marca varchar(45) NOT NULL,
    tipo varchar(45) NOT NULL,
    fk_cuenta INTEGER NOT NULL,
    anyo_vencimiento INTEGER NOT NULL,
    mes_vencimiento INTEGER NOT NULL,
    activa TINYINT NOT NULL DEFAULT '0',
    PRIMARY KEY (id_tarjeta),
    CONSTRAINT tarjetas_cuentas FOREIGN KEY (fk_cuenta) REFERENCES cuentas (id_cuenta)
);

CREATE TABLE tipos_movimientos (
    id_tipo_movimiento INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tipo_movimiento varchar(45) NOT NULL,
    PRIMARY KEY (id_tipo_movimiento)
);

CREATE TABLE movimientos (
    id_movimiento INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fk_tipo_mov INTEGER NOT NULL,
    fk_tarjeta INTEGER NOT NULL,
    fk_extracto INTEGER DEFAULT NULL,
    fecha date NOT NULL,
    importe decimal(10,2) NOT NULL,
    proveedor varchar(45) NOT NULL,
    PRIMARY KEY (id_movimiento),
    CONSTRAINT movimientos_extractos FOREIGN KEY (fk_extracto) REFERENCES extractos (id_extracto),
    CONSTRAINT movimientos_tarjetas FOREIGN KEY (fk_tarjeta) REFERENCES tarjetas (id_tarjeta),
    CONSTRAINT movimientos_tipos FOREIGN KEY (fk_tipo_mov) REFERENCES tipos_movimientos (id_tipo_movimiento)
);

-- Índices secundarios del volcado original
CREATE INDEX cuenta_cliente_idx ON cuentas (fk_cliente);
CREATE INDEX extractos_cuentas_idx ON extractos (fk_cuenta);
CREATE INDEX tarjetas_cuentas_idx ON tarjetas (fk_cuenta);
CREATE INDEX movimientos_tipos_idx ON movimientos (fk_tipo_mov);
CREATE INDEX movimientos_tarjetas_idx ON movimientos (fk_tarjeta);
CREATE INDEX movimientos_extractos_idx ON movimientos (fk_extracto);

